import './Innovate.css'

import { useLayoutEffect } from 'react';
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

function Innovate() {

  useLayoutEffect(()=>{

      // Mobile view me animation band
  if (window.innerWidth <= 768) return;
  
    const ctx = gsap.context(()=>{
      const timer = setTimeout(()=>{

     
    gsap.fromTo('.innovate .innovate-hadding',{
      x:200,
      opacity:0

    },{
      x:0,
      opacity:1,
      delay:.7,
      scrollTrigger:{
        trigger:'.innovate',
        start:'top 80%',
        toggleActions:'play none none reset'
      }

    })

     gsap.fromTo('.innovate .innovate-left-side',{
      x:-100,
      opacity:0

    },{
      x:0,
      opacity:1,
      delay:1.2,
      scrollTrigger:{
        trigger:'.innovate',
        start:'top 80%',
        toggleActions:'play none none reset'
      }

    })

     gsap.fromTo('.innovate .innovate-right-side',{
      scale:0,
      opacity:0

    },{
      scale:1,
      opacity:1,
      delay:1.7,
      scrollTrigger:{
        trigger:'.innovate',
        start:'top 80%',
        toggleActions:'play none none reset'
      }

    })
    ScrollTrigger.refresh()

     },500);
     return()=>clearTimeout(timer)
     
    })
    return ()=>ctx.revert()
  },[]);
  return (
    <section className="innovate">
      <div className="container">
        <h1 className="innovate-hadding">
          <span className="innovate-span">Innovate</span>DESIGN AND TECHNOLOGY
        </h1>

        <div className="innovate-flex">
          <div className="innovate-left-side">
            <img
              src="https://www.bdsinternationalschool.net/image/videobg.webp"
              alt=""
            />
          </div>

          <div className="innovate-right-side">
            <div className="innovate-grid">
              <img
                src="https://www.bdsinternationalschool.net/image/icon1.webp"
                alt=""
              />
              <h5>VR Lab</h5>
            </div>

            <div className="innovate-grid">
              <img
                src="https://www.bdsinternationalschool.net/image/icon2.webp"
                alt=""
              />
              <h5>Clubs</h5>
            </div>

            <div className="innovate-grid robotic">
              <img
                src="https://www.bdsinternationalschool.net/image/icon3.webp"
                alt="" 
              />
              <h5>Robotics</h5>
            </div>

            <div className="innovate-grid">
              <img
                src="https://www.bdsinternationalschool.net/image/icon4.webp"
                alt=""
              />
              <h5>Sports</h5>
            </div>

            <div className="innovate-grid">
              <img
                src="https://www.bdsinternationalschool.net/image/icon5.webp"
                alt=""
              />
              <h5>Each Class Smart Class</h5>
            </div>

            <div className="innovate-grid">
              <img
                src="https://www.bdsinternationalschool.net/image/icon6.webp"
                alt=""
              />
              <h5>Geeta Studies : Part Of Curriculum</h5>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
export default Innovate;
