import { Link } from 'react-router-dom';
import './Mobile-Navbar.css'

function MobileNavbar({ openNav, setOpenNav }){
  
  

    return(

        <div className="mobile-navbar" style={{left:openNav ? "0px": '-500px'}}>
        <div className="close-icon" onClick={()=> setOpenNav(false)}><i className="fa-regular fa-circle-xmark"></i></div>
        <div className="mobile-nav-image">
          <img src="https://bdsinternationalschool.net/image/logo.png" alt=""/>
        </div>
        <div className="ul-scroll">
        <ul>
          <li><Link to="/" onClick={() => setOpenNav(false)}>Home</Link></li>
          <li><Link to="/About" onClick={() => setOpenNav(false)}>ABout Us</Link></li>
          <li><Link to="/Sports" onClick={() => setOpenNav(false)}>Infrastructure</Link></li>
          <li><Link to="/Admission" onClick={() => setOpenNav(false)}>Guideline</Link></li>
          <li><Link to="/TEDx" onClick={() => setOpenNav(false)}>Tedx</Link></li>
          <li><Link to="/News" onClick={() => setOpenNav(false)}>News</Link></li>
          <li><Link to="/Vacancy" onClick={() => setOpenNav(false)}>Vacancy</Link></li>
          <li><Link to="/" onClick={() => setOpenNav(false)}>Gallery</Link></li>
          <li><Link to="/" onClick={() => setOpenNav(false)}>Contact us</Link></li>
          <li><Link to="/" onClick={() => setOpenNav(false)}>online Fee PAYMENT</Link></li>
          <li><Link to="/" onClick={() => setOpenNav(false)}>MANDATORY DISCLOSURE</Link></li>
          <li><Link to="/" onClick={() => setOpenNav(false)}>Board Class toppers</Link></li>
          <li><Link to="/" onClick={() => setOpenNav(false)}>Fee STRUCTURE</Link></li>
        </ul>
        </div>
        <div className="mobile-nav-icon">
          <div className="mobile-nav-icon-box"><i className="fa-brands fa-facebook"></i></div>
          <div className="mobile-nav-icon-box"><i className="fa-brands fa-instagram"></i></div>
          <div className="mobile-nav-icon-box"><i className="fa-brands fa-youtube"></i></div>
        </div>
      </div>
    )

}

export default MobileNavbar;