import { useEffect } from 'react';
import './Images.css'

import gsap from 'gsap';

function Images() {
  useEffect(()=>{
    gsap.fromTo('.images',{
      scale:0,
      opacity:0
    },{
      scale:1,
      opacity:1,
      duration:1,
      delay:2,
    })
  })
  return (
    <div class="slider">
      <div className="images">
        <img
          src="https://bdsinternationalschool.net/assets/banner/1732685969.jpg"
          alt=""
        />
        
      </div>
    </div>
  );
}
export default Images;
