import "./Learn.css";
import { Link } from "react-router-dom";

import { useLayoutEffect } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

function Learn() {

 useLayoutEffect(() => {
  
    // Mobile view me animation band
  if (window.innerWidth <= 768) return;

  const ctx = gsap.context(() => {

    const timer = setTimeout(() => {

      gsap.fromTo(
        "#icons .motion",
        {
          y: 50,
          opacity: 0,
        },
        {
          y: 0,
          opacity: 1,
          duration: 0.5,
          stagger: 0.2,
          ease: "power3.out",

          scrollTrigger: {
            trigger: "#icons",
            start: "top 80%",
            toggleActions: "play none none reset",
          },
        }
      );

      gsap.fromTo(
        ".classroom-scaleUp",
        {
          x: 100,
          opacity: 0,
        },
        {
          x: 0,
          opacity: 1,
          duration: 1,
          ease: "power3.out",

          scrollTrigger: {
            trigger: ".classroom",
            start: "top 75%",
            toggleActions: "play none none reset",
          },
        }
      );

      ScrollTrigger.refresh();

    }, 500);

    return () => clearTimeout(timer);

  });

  return () => ctx.revert();

}, []);

  return (
    <section className="detail" id="icons">

      <div className="container">

        <h1 className="heading motion">
          <span className="learn">Learn</span>
          APPROACH AND CURRICULUM
        </h1>

        <p className="p1-details motion">
          We, at BDS International School take pride in its excellent
          infrastructure and student centered environment.
        </p>

        <p className="p1-details motion">
          BDS International School is the product of a vision,
          a dream of Excellence.
        </p>

        <div className="detail-items">

          <ul>

            <li className="motion">
              <Link to="/Sports">Sports</Link>
            </li>

            <li className="motion">
              <Link to="/KinderGarten">KinderGarten</Link>
            </li>

            <li className="motion">
              <Link to="/SchoolLibrary">School Library</Link>
            </li>

            <li className="motion">
              <Link to="/Transport">Transport</Link>
            </li>

            <li className="motion">
              <Link to="/Club">Clubs</Link>
            </li>

          </ul>

        </div>

        <div className="classroom classroom-scaleUp">

          <div className="teacher">

            <div className="img-circle">
              <img
                src="https://www.bdsinternationalschool.net/image/teacher.webp"
                alt="teacher icon"
              />
            </div>

            <div className="teacher-img-text">
              <h1>80+</h1>
              <h3>Teachers</h3>
            </div>

          </div>

          <div className="teacher">

            <div className="img-circle">
              <img
                src="https://www.bdsinternationalschool.net/image/student.webp"
                alt="student icon"
              />
            </div>

            <div className="teacher-img-text">
              <h1>1700+</h1>
              <h3>Students</h3>
            </div>

          </div>

          <div className="teacher">

            <div className="img-circle">
              <img
                src="https://www.bdsinternationalschool.net/image/classroom.webp"
                alt="classroom icon"
              />
            </div>

            <div className="teacher-img-text">
              <h1>100+</h1>
              <h3>Classrooms</h3>
            </div>

          </div>

        </div>

      </div>

    </section>
  );
}

export default Learn;