import "./Explore.css";

import { useLayoutEffect } from 'react';
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);


function Explore() {
  useLayoutEffect(()=>{

      // Mobile view me animation band
  if (window.innerWidth <= 768) return;
  
    const ctx = gsap.context(()=>{
      const timer = setTimeout(()=>{

     
    gsap.fromTo('.explore .explore-h1',{
      x:200,
      opacity:0

    },{
      x:0,
      opacity:1,
      scrollTrigger:{
        trigger:'.explore',
        start:'top 80%',
        toggleActions:'play none none reset'
      }

    })

    gsap.fromTo('.explore .explore-item-box',{
      y:200,
      opacity:0

    },{
      y:0,
      opacity:1,
      delay:.5,
      stagger:.3,
      scrollTrigger:{
        trigger:'.explore',
        start:'top 80%',
        toggleActions:'play none none reset'
      }

    })
    ScrollTrigger.refresh()
     },500);
     return()=>clearTimeout(timer)
    })
    return ()=>ctx.revert()
  },[])
  return (
    <section className="explore">
      <div className="container">
        <h1 className="explore-h1">
          <span className="explore-span">Explore</span>PROGRAMS AND EXPERIENCES
        </h1>
        <div className="explore-item-grid">
          <div className="explore-item-box">
            <figure className="explore-item-box-Full-img">
              <img
                src="https://www.bdsinternationalschool.net/image/Ace1.jpg"
                alt=""
              />
            </figure>
          </div>

          <div className="explore-item-box">
            <figure className="explore-item-box-img">
              <img
                src="https://www.bdsinternationalschool.net/image/virtual%20labs.jpg"
                alt=""
              />
            </figure>
            <div className="explore-item-box-text">
              <h3>Virtual reality Lab</h3>
              <p>
                Experience immersive learning with state-of-the-art VR
                Technology.
              </p>
            </div>
          </div>

          <div className="explore-item-box">
            <figure className="explore-item-box-Full-img">
              <img
                src="https://www.bdsinternationalschool.net/image/Ace2.jpg"
                alt=""
              />
            </figure>
          </div>

          <div className="explore-item-box">
            <div className="explore-item-box-text">
              <h3>geeta studies</h3>
              <p>
                Integrating ancient wisdom into modern curriculum for holistic
                growth.
              </p>
            </div>
            <figure className="explore-item-box-img">
              <img
                src="https://www.bdsinternationalschool.net/image/geeta.jpg"
                alt=""
              />
            </figure>
          </div>

          <div className="explore-item-box"></div>

          <div className="explore-item-box">
            <figure className="explore-item-box-img">
              <img
                src="https://www.bdsinternationalschool.net/image/smart%20classses.jpg"
                alt=""
              />
            </figure>
            <div className="explore-item-box-text">
              <h3>Smart Class</h3>
              <p>
                Interactive digital classroom enhancing engagement and
                understanding.
              </p>
            </div>
          </div>

          <div className="explore-item-box">
            <figure className="explore-item-box-Full-img">
              <img
                src="https://www.bdsinternationalschool.net/image/Smart1.jpg"
                alt=""
              />
            </figure>
          </div>

          <div className="explore-item-box">
            <div className="explore-item-box-text">
              <h3>Ace Program</h3>
              <p>Accelerating excellence and unlocking potential.</p>
            </div>
            <figure className="explore-item-box-img">
              <img
                src="https://www.bdsinternationalschool.net/image/ace.jpg"
                alt=""
              />
            </figure>
          </div>

          <div className="explore-item-box">
            <figure className="explore-item-box-Full-img">
              <img
                src="https://www.bdsinternationalschool.net/image/Virtual3.jpg"
                alt=""
              />
            </figure>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Explore;
