import './Contect.css'
import { gsap } from "gsap";
import { useEffect} from "react";
import { useState} from "react";

import MobileNavbar from '../Mobile-Navbar/Mobile-Navbar';

function Contect(){

  const [openNav, setOpenNav] = useState(false);

  useEffect(()=>{
    gsap.fromTo('.logo',{
      x:-100,
      opacity:0,
      duration:1,
      

    },{
      x:0,
      opacity:1,
      duration:1,
      delay:1.5
    })

    gsap.fromTo('.popUp',{
      x:100,
      opacity:0,
      duration:1

    },{
      x:0,
      opacity:1,
      duration:1,
      stagger:.3,
      delay:1.5
    })
    gsap.fromTo('.scaleUp',{
      opacity:0,
    },{
      opacity:1,
      delay:3,
      repeat: -1,
      yoyo: true,
      duration:1,
      keyframes: [
    { opacity: 1 },
    { opacity: 0 },
    { opacity: 1 }
  ]
    })
  },[])

  // Mobile Navbar
  


  // Mobile Navbar
    return(
      <>
          {/* Mobile Navbar */}
    <MobileNavbar openNav={openNav} setOpenNav={setOpenNav} />

        <section className="contect-section">
      <div className="container">
        
        <div className="contect">
          <div className="logo">
            <img
              src="https://bdsinternationalschool.net/image/logo.png"
              alt="Logo"
            />
          </div>

           {/* Hamburger Icon */}
          <div
            className="humberger-icon"
            onClick={() => setOpenNav(true)}
          >
            <i className="fa-solid fa-bars"></i>
          </div>

          <div className="info-container popUp">
            <div className="info">
              <p>School Code : 60633</p>
              <p>Affiliation No. : 2131417</p>
            </div>
          </div>

          <div className="info-container popUp">
            <div className="info-icon">
              <i className="fa-solid fa-phone"></i>
            </div>
            <div className="info">
              <p>CONTACT US</p>
              <p>8171605615, 8171605888</p>
            </div>
          </div>

          <div className="info-container popUp">
            <div className="info-icon">
              <i className="fa-solid fa-envelope"></i>
            </div>
            <div className="info">
              <p>Mail ID</p>
              <p>bdsischool@gmail.com</p>
            </div>
          </div>

          <div className="info-container popUp">
            <div className="info-icon">
              <i className="fa-solid fa-envelope"></i>
            </div>
            <div className="info">
              <p>Mail ID</p>
              <p>communications@bdsis.edu.in</p>
            </div>
          </div>
        </div>
        <h3 className='scaleUp'>Admissions Open 2026-2027. Enroll Now</h3>
      </div>
    </section>
    </>
    )
}

export default Contect;